def verify(root):
    for relative, url, expected in FILES:
        if hashlib.sha256((root / relative).read_bytes()).hexdigest() != expected:
            raise RuntimeError('Hash mismatch: '+relative)

def main():
    if len(sys.argv) == 3 and sys.argv[1] == '--verify-only':
        verify(Path(sys.argv[2])); print('All staged file hashes verified'); return
    if len(sys.argv) != 1:
        raise RuntimeError('Unsupported arguments')
    if os.geteuid() != 0:
        raise RuntimeError('Run as root on srv920347')
    os.umask(0o077)
    root = Path(tempfile.mkdtemp(prefix='pachimind-personas-stage-', dir='/srv/pachimind'))
    print('STAGE:', root, flush=True)
    for relative, url, expected in FILES:
        target = root / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        with urlopen(Request(url, headers={'User-Agent':'PachiMind-release-stage'}), timeout=45) as response:
            data = response.read()
        if hashlib.sha256(data).hexdigest() != expected:
            raise RuntimeError('Hash mismatch: '+relative)
        target.write_bytes(data)
    verify(root)
    (root/'manifest.json').write_text(json.dumps(FILES, indent=2)+'\n')
    env = dict(os.environ, VAULT_PATH='/tmp/pachimind-tests-unused', PYTHONDONTWRITEBYTECODE='1')
    env.pop('PACHIMIND_TEST_API_URL', None)
    checks = [('api','/srv/pachimind/api/.venv/bin/python'), ('mcp','/srv/pachimind/mcp/.venv/bin/python')]
    for component, python in checks:
        print('TEST:', component, flush=True)
        # The subprocess output stays in private staging; no app logs are pasted.
        log = root/(component+'-tests.log')
        with log.open('w') as output:
            result = subprocess.run([python,'-m','unittest','discover','-s','tests','-v'],cwd=root/component,env=env,stdout=output,stderr=subprocess.STDOUT)
        lines=log.read_text(errors='replace').splitlines()
        for line in lines:
            if line.startswith('Ran ') or line == 'OK' or line.startswith('OK (') or line.startswith('FAILED '):
                print(line, flush=True)
        if result.returncode:
            print('Private test log:', log, flush=True)
            raise RuntimeError(component+' tests failed; production unchanged')
    for path in ['dist/server.cjs','dist/people.js']:
        subprocess.run(['node','--check',str(root/'web'/path)],check=True,stdout=subprocess.DEVNULL)
    (root/'READY').write_text('Verified staging only. Production unchanged.\n')
    print('READY:', root, flush=True)
    print('Production unchanged. No services restarted.', flush=True)

if __name__ == '__main__':
    try: main()
    except Exception as exc:
        print('STOP:',type(exc).__name__,str(exc),file=sys.stderr)
        sys.exit(1)
